    Bug 2003107 - Fix intermittent background timer leaks in browser_offlineSettings.js. r=mkmelin


    Toggling offline flags triggered `nsAutoSyncManager` download timers.
    These are suppressed by disabling the
    `mail.server.default.autosync_offline_stores` preference for the
    duration of the test.

    Differential Revision: https://phabricator.services.mozilla.com/D286556

diff --git a/mail/test/browser/account/browser_offlineSettings.js b/mail/test/browser/account/browser_offlineSettings.js
index f1119eb96be..79d0c20b5e8 100644
--- a/mail/test/browser/account/browser_offlineSettings.js
+++ b/mail/test/browser/account/browser_offlineSettings.js
@@ -23,6 +23,13 @@ let imapAccount, imapRootFolder;
 let ewsAccount, ewsRootFolder;

 add_setup(async () => {
+  // Disable AutoSync so toggling offline flags doesn't trigger background
+  // download timers that leak past the end of the test.
+  Services.prefs.setBoolPref(
+    "mail.server.default.autosync_offline_stores",
+    false
+  );
+
   // Set up servers.

   const imapServer = await ServerTestUtils.createServer({ type: "imap" });
@@ -128,6 +135,7 @@ add_setup(async () => {
     MailServices.accounts.removeAccount(nntpAccount, false);
     MailServices.accounts.removeAccount(imapAccount, false);
     MailServices.accounts.removeAccount(ewsAccount, false);
+    Services.prefs.clearUserPref("mail.server.default.autosync_offline_stores");
     tabmail.closeOtherTabs(0);
   });
 });
